// V4.21 — editor-only preview quality. This is a device preference, not part
// of the project file, so changing it never changes export/project semantics.
const OMS_PREVIEW_QUALITY_KEY='oms_preview_quality';
const OMS_PREVIEW_QUALITY_VALUES=new Set(['auto','1','0.75','0.5','0.25']);
function omsPreviewQualityPreference(){
  let value='auto';
  try{value=localStorage.getItem(OMS_PREVIEW_QUALITY_KEY)||'auto'}catch(e){}
  return OMS_PREVIEW_QUALITY_VALUES.has(value)?value:'auto'
}
function omsPreviewQualityScale(){
  const pref=omsPreviewQualityPreference();
  if(pref!=='auto')return clamp(parseFloat(pref)||1,.25,1);
  let coarse=false,narrow=false;
  try{coarse=matchMedia('(pointer:coarse)').matches;narrow=matchMedia('(max-width:899px)').matches}catch(e){}
  const memory=Number(navigator.deviceMemory)||0;
  // Mobile/touch defaults to half-resolution preview; desktop to 75%.
  // Very low-memory devices keep a slightly more conservative automatic tier.
  if(coarse&&narrow)return memory&&memory<=3?.35:.5;
  if(memory&&memory<=3)return .5;
  return .75
}
function omsPreviewQualityPercent(){return Math.round(omsPreviewQualityScale()*100)}
function omsSetPreviewQuality(value){
  const next=OMS_PREVIEW_QUALITY_VALUES.has(String(value))?String(value):'auto';
  try{localStorage.setItem(OMS_PREVIEW_QUALITY_KEY,next)}catch(e){}
  bus.emit('preview:quality',{preference:next,scale:omsPreviewQualityScale()});
  return next
}

