      const blob=known instanceof Blob?known:await media.sourceBlobForLayer(l);if(!(blob instanceof Blob))return null;
      let entry=blobs.get(blob);if(!entry){entry={meta:null,task:null};entry.task=probe(blob).then(meta=>(entry.meta=meta));blobs.set(blob,entry)}
