    const box=document.createElement('div');box.style.cssText='width:min(760px,100%);max-height:88vh;max-height:88dvh;overflow:auto;background:#f7f7f9;color:#171923;border-radius:18px 18px 12px 12px;padding:14px;box-shadow:0 20px 70px rgba(0,0,0,.48)';
    const categories=OMS_DIAGNOSTIC_DEFS.map(([id,label,desc])=>`<label style="display:grid;grid-template-columns:1fr auto;gap:10px;align-items:center;padding:10px 0;border-bottom:1px solid #e2e4ea"><span><b style="display:block;font-size:13px">${label}</b><small style="display:block;color:#6d7280;font-size:11px;line-height:1.3;margin-top:2px">${desc}</small></span><input data-diag-category="${id}" type="checkbox" ${this.prefs.categories[id]?'checked':''}></label>`).join('');
