  device(){let coarse=false;try{coarse=matchMedia('(pointer:coarse)').matches||navigator.maxTouchPoints>0}catch(e){}return{memory:Math.max(0,+navigator.deviceMemory||0),cores:Math.max(1,+navigator.hardwareConcurrency||4),coarse}}
  heuristicMax(){const d=this.device();if(!d.coarse)return d.cores>=12?10:d.cores>=8?8:6;if(d.memory>=12&&d.cores>=8)return 10;if(d.memory>=8&&d.cores>=8)return 8;if(d.memory>=6&&d.cores>=8)return 6;if(d.memory>=4&&d.cores>=6)return 5;return 4}
