  observeFrame(dtMs,frameMs){if(!window.omsNativeMultiSourceDirectPlayback||this.activeCount<=4)return;this.windowFrames++;this.windowMaxDt=Math.max(this.windowMaxDt,+dtMs||0);if((+dtMs||0)>frameMs*1.55)this.windowJank++;if(this.windowFrames<90)return;const ratio=this.windowJank/Math.max(1,this.windowFrames),now=performance.now();let next=this.runtimePressure;if(ratio>.055||this.windowMaxDt>frameMs*2.6)next=Math.min(3,next+1);else if(ratio<.012&&this.windowMaxDt<frameMs*1.9){this.stableWindows++;if(this.stableWindows>=2)next=Math.max(0,next-1)}else this.stableWindows=0;if(next!==this.runtimePressure&&now-this.lastPressureChange>900){const before=this.runtimePressure;this.runtimePressure=next;this.lastPressureChange=now;this.stableWindows=0;omsDiagnostics.log('video','NATIVE_CAPACITY_PRESSURE',`${before}→${next}`,{sources:this.activeCount,jankRatio:+ratio.toFixed(4),maxDtMs:+this.windowMaxDt.toFixed(2),recommended:this.recommendedMax(),hardLimit:this.hardLimit()})}this.windowFrames=0;this.windowJank=0;this.windowMaxDt=0}
