  shouldUpload(layer,token,initialized){if(!initialized)return true;const div=this.uploadDivisor(layer);if(div<=1)return true;let phase=0;for(const ch of String(layer?.id||''))phase=(phase+ch.charCodeAt(0))%div;const ok=(Math.max(0,Math.round(+token||0))%div)===phase;if(!ok)this.adaptiveTextureSkips++;return ok}
