  constructor(capacity){this.capacity=capacity;this.running=false;this.clip=null;this.clipBuffer=null;this.mime='';this.modal=null}
  supportedMime(){if(typeof MediaRecorder==='undefined')return'';for(const m of ['video/webm;codecs=vp8','video/webm;codecs=vp9','video/webm'])try{if(!MediaRecorder.isTypeSupported||MediaRecorder.isTypeSupported(m))return m}catch(e){}return''}
  async makeClip(status=()=>{}){if(this.clip)return this.clip;const mime=this.supportedMime();if(!mime||!HTMLCanvasElement.prototype.captureStream)throw new Error('MediaRecorder/captureStream tidak tersedia');status('Menyiapkan klip uji 1080p…');const c=document.createElement('canvas');c.width=1920;c.height=1080;const ctx=c.getContext('2d',{alpha:false});const stream=c.captureStream(30),chunks=[];const rec=new MediaRecorder(stream,{mimeType:mime,videoBitsPerSecond:6000000});rec.ondataavailable=e=>{if(e.data?.size)chunks.push(e.data)};const done=new Promise((resolve,reject)=>{rec.onstop=resolve;rec.onerror=e=>reject(e.error||new Error('MediaRecorder gagal'))});rec.start(200);const start=performance.now(),duration=3300;await new Promise(resolve=>{const draw=now=>{const t=(now-start)/1000;ctx.fillStyle='#101827';ctx.fillRect(0,0,1920,1080);for(let i=0;i<8;i++){const x=((t*260+i*270)%2300)-220;ctx.fillStyle=`hsl(${(i*43+t*70)%360} 78% 55%)`;ctx.fillRect(x,80+i*112,420,82)}ctx.fillStyle='#ffffff';ctx.font='700 96px system-ui';ctx.fillText('Open Motion 1080p Native Test',110,520);ctx.font='500 54px system-ui';ctx.fillText(`${t.toFixed(2)} s`,110,610);if(now-start<duration)requestAnimationFrame(draw);else resolve()};requestAnimationFrame(draw)});try{rec.stop()}catch(e){}await done;for(const tr of stream.getTracks())try{tr.stop()}catch(e){}this.mime=mime;this.clip=new Blob(chunks,{type:mime});this.clipBuffer=await this.clip.arrayBuffer();return this.clip}
