        l.frameCtx=item.frameCtx;
        l.frameCacheReady=item.frameCacheReady;
        l.frameCacheTime=item.frameCacheTime;
        if(item.verified===undefined)delete l._preRenderSequentialVerifiedTarget;else l._preRenderSequentialVerifiedTarget=item.verified;
