        const blob=await this.sourceBlobForLayer(l);
        if(!(blob instanceof Blob)||state.disposed)throw Error('Blob media tidak tersedia');
        input=new mod.Input({formats:mod.ALL_FORMATS,source:new mod.BlobSource(blob)});
        const track=await input.getPrimaryVideoTrack();
        if(!track||!(await track.canDecode()))throw Error('Codec tidak didukung WebCodecs');
        const displayW=Math.max(2,+await track.getDisplayWidth()||2);
        const displayH=Math.max(2,+await track.getDisplayHeight()||2);
        const sourceLong=Math.max(displayW,displayH);
        const targetLong=Math.min(sourceLong,this.previewLongEdge());
