      delete l._sharedVideoLeaderId;
      if(!keepProxies&&l._sharedAudioProxy){try{l._sharedAudioProxy.pause();l._sharedAudioProxy.src=''}catch(e){};delete l._sharedAudioProxy;this.sharedAudioClockStates.delete(l.id)}
