    const now=performance.now();if(this.sharedPlaybackPrewarmStamp>0&&now-this.sharedPlaybackPrewarmStamp<500)return;
    this.sharedPlaybackPrewarmStamp=now;
    const duration=Math.max(0,+this.model.project?.duration||0),times=[];
    for(const d of [.35,.7,1.05,1.25]){const x=Math.min(duration,Math.max(0,(+t||0)+d));if(!times.includes(x))times.push(x)}
