// Phase 2 service boundary: coalesces editor invalidations without owning the
// model, UI, timeline, or renderer. Invariants: newest job wins per key, at
// most one RAF is pending, queued mutations run in insertion order, and the
// single render request runs only after those mutations.
class EditorInvalidationScheduler{
  constructor(){
    this.jobs=new Map();
    this.raf=0;
    this.renderRequested=false;
  }

  request(key,fn=()=>{},{render=true}={}){
    // Only the newest sample for a gesture survives until the next screen
    // refresh. Old pointer samples are intentionally discarded.
    this.jobs.set(key,fn);
    if(render)this.renderRequested=true;
    if(!this.raf)this.raf=requestAnimationFrame(()=>this.flush());
  }

  // Compatibility facade for the V4.28 interaction call sites that have not
  // been migrated in this phase.
  schedule(key,fn,render=true){this.request(key,fn,{render})}

  requestRender(key='render'){
    this.schedule(key,()=>{},true);
  }

  flush(){
    this.raf=0;
    if(!this.jobs.size&&!this.renderRequested)return;

    const jobs=[...this.jobs.values()];
    this.jobs.clear();
    for(const fn of jobs){
      try{fn()}catch(e){console.error(e)}
    }

    const shouldRender=this.renderRequested;
    this.renderRequested=false;
    if(shouldRender)renderer.render();

    if((this.jobs.size||this.renderRequested)&&!this.raf){
      this.raf=requestAnimationFrame(()=>this.flush());
    }
  }

  flushNow(key=null){
    if(this.raf){
      cancelAnimationFrame(this.raf);
      this.raf=0;
    }

    if(key!==null){
      const fn=this.jobs.get(key);
      if(fn){
        this.jobs.delete(key);
        try{fn()}catch(e){console.error(e)}
      }
    }else{
      const jobs=[...this.jobs.values()];
      this.jobs.clear();
      for(const fn of jobs){
        try{fn()}catch(e){console.error(e)}
      }
    }

    const shouldRender=this.renderRequested;
    this.renderRequested=false;
    if(shouldRender)renderer.render();
  }

  cancel(key){
    this.jobs.delete(key);
  }
}

