const renderer=new WebGLRenderer(model,$('#stage'));
const editorInvalidation=new EditorInvalidationScheduler();
const interaction=editorInvalidation;

bus.on('video:frame',(layerId)=>{
  // During playback the decoded-frame callback also drives progressive capture.
  // This makes Play #1 cache immediately instead of depending on frames left warm
  // by an earlier traversal.
  const pre=window.omsTimelinePreRender;
  if(model.playing){
    // V5.24 — the playback clock already composites native multi-source frames through direct WebGL video texture uploads.
    // Do not let four requestVideoFrameCallback streams trigger additional
    // pre-render captures/renders on top of that clock.
    if(media.nativeMultiSourcePlayback)return;
    pre?.onPlaybackVideoFrame?.(layerId);
    return
  }
  // A cached scrub frame is authoritative while the finger is moving. On a
  // cache miss, MediaManager may explicitly approve an intermediate WebCodecs
  // frame from the CURRENT scrub direction. Slow, timestamp-verified live scrub
  // frames are allowed to populate pre-render through the renderer facade.
  const layer=model.layers.find(candidate=>candidate?.id===layerId);
  const approvedInteractive=!!layer?._interactiveScrubFrameApproved;
  const allowDecoder=!pre?.scrubActive || pre?.allowLiveScrubRender?.() ||
    (pre?.scrubDisplaySource==='live'&&approvedInteractive);
  if(!renderer.domInteraction&&allowDecoder)editorInvalidation.requestRender('decoded-video-frame');
});

