    const entry=this.frames.get(frame);
    if(!entry||entry.bitmap||!entry.blob||entry.promoting||this.promoteQueued.has(frame))return false;
    this.promoteQueued.add(frame);
    priority?this.promoteQueue.unshift(frame):this.promoteQueue.push(frame);
