      if(cache.scrubActive&&(cache.scrubDisplaySource==='cache'||cache.scrubDisplaySource==='cache-pending'))return;
      cache.hide();
      const result=cache.originalRender(...args);
      if(!cache.captureSuppressDepth&&(!cache.model.project?.amGPU||(cache.renderer.amFramePresented&&Math.abs(cache.renderer.amPresentedTime-cache.model.time)<1e-7)))cache.captureCurrent();
