    $$('[data-addhub]').forEach(b=>b.onclick=()=>this.openTool(b.dataset.addhub));
    $('#addHubClose')?.addEventListener('click',()=>this.closeDrawer());
    $$('[data-add]').forEach(b=>b.onclick=()=>{history.push();model.addLayer('shape',{shape:b.dataset.add,name:b.dataset.add==='ellipse'?'Ellipse':'Shape'});this.rebuildAll();this.openInspectorRoot()});
    $$('[data-obj]').forEach(b=>b.onclick=()=>{history.push();const o=b.dataset.obj;if(o==='camera'){model.addLayer('camera');model.mode3d=true}else if(o==='null')model.addLayer('null');else{model.addLayer('mesh',{mesh:o});model.mode3d=true}this.rebuildAll();this.openInspectorRoot()});
