    editor.append(dock);state.touchpadDock=dock;state.touchpad=dock.querySelector('#vectorPenTouchpad');state.touchpadFinger=dock.querySelector('.vectorPenTouchpadFinger');state.leftRail=dock.querySelector('.vectorPenLeftRail');state.editPad=dock.querySelector('#vectorPenEditPad');state.editPointer=null;state.editOverview=dock.querySelector('.vectorPenEditOverview');
