    const state=this.vectorPenState={overlay,hud:null,hint:null,nodes:existingNodes,cursor:{...initialCursor},editCursor:{...initialCursor},selectedIndex:-1,editTarget:null,closed:!!editLayer?.vectorClosed,dragIndex:-1,pointerId:null,touchpadDock:null,touchpad:null,touchpadFinger:null,leftRail:null,editPad:null,editPointer:null,editOverview:null,selectionBadge:null,navActive:false,navU:0,navSegmentIndex:-1,navT:0,navPoint:null,navScroll:0,endpointMode:null,endpointCursor:null,liveLayerId:editLayer?.id||null,vectorHistoryLayerId:editLayer?.id||null,canvasHistoryPushed:false,preRenderInvalidatedForVectorEdit:false};
    this.installVectorPenTouchpad(state);const badge=document.createElement('div');badge.className='vectorPenSelectionBadge';badge.textContent='Tidak ada titik terpilih';($('#viewport')||wrap).append(badge);state.selectionBadge=badge;
