    bindSpring('effectEaseStiffness','effectEaseStiffnessN','stiffness',20,400);bindSpring('effectEaseDamping','effectEaseDampingN','damping',1,60);bindSpring('effectEaseMass','effectEaseMassN','mass',.1,5);
