    l.kf ||= {};for(const [paramId,keys] of Object.entries(payload.keyframes||{})){const path=omsEffectParamPath(inst.instanceId,paramId);l.kf[path]=(keys||[]).map(key=>({...this.effectClone(key),id:uid('kf')}))}
