        const prefix=`effect.${inst.instanceId}.`;for(const path of Object.keys(l.kf||{}))if(path.startsWith(prefix))delete l.kf[path];
        this.effectActiveInstanceId=inst.instanceId;this.effectActiveParamId='rate';
        invalidate('particular-preset');
