        if(!model.anim.hasKeyAt(l,path,editTime,tolerance))model.anim.setKey(l,path,editTime,Number(omsEffectRawValue(l,inst,param.id,editTime))||0,{type:'hold'},tolerance);
        const gesture={editTime,keyframeHit:!!hit};setValue(param,input.checked?1:0,input,gesture);keyButtonFor(param)?.classList.add('on');timeline.rebuild();renderer.render();input._omsEffectEditing=false;this.updateEffectLiveValues(l)
