        history.push();const on=model.anim.toggleKey(l,path,model.time,value);button.classList.toggle('on',on);if(spec?.id==='particular')this.updateParticularPresetVisuals(card,l,inst,spec);timeline.rebuild();invalidate('effect-key-toggle');this.updateEffectLiveValues(l)
