    camera.parentId=null;camera.orbitTargetId=target.id;
    camera.orbitFollowPosX=!!next.posX;camera.orbitFollowPosY=!!next.posY;camera.orbitFollowPosZ=!!next.posZ;
    camera.orbitFollowRotX=!!next.rotX;camera.orbitFollowRotY=!!next.rotY;camera.orbitFollowRotZ=!!next.rotZ;
    camera.orbitBindTargetX=Number(rawTarget.x)||0;camera.orbitBindTargetY=Number(rawTarget.y)||0;camera.orbitBindTargetZ=Number(rawTarget.z)||0;
    camera.orbitBindTargetRotX=Number(p.rotX)||0;camera.orbitBindTargetRotY=Number(p.rotY)||0;camera.orbitBindTargetRotZ=(Number(p.rotZ)||0)+(Number(p.rotation)||0);
