    home?.classList.remove('projectSelectionMode');bar?.classList.remove('active');
    if(fab&&!$('#newModal')?.classList.contains('hidden')){fab.style.display='none';fab.style.pointerEvents='none'}
    else if(fab){fab.style.display='';fab.style.pointerEvents='auto'}
