window.omsAMGPU=AMEffectGPU;
const amParseBeforeGPU=AMNativeSceneImporter.parse.bind(AMNativeSceneImporter);
AMNativeSceneImporter.parse=function(...args){const scene=amParseBeforeGPU(...args);scene.project.amGPU=true;scene.project.amImportVersion=192;scene.project.amWarnings=[];for(const l of scene.layers){if(l.amImport?.previewDisabled){l.hidden=!!l.amImport.originalHidden;delete l.amImport.previewDisabled;delete l.amImport.originalHidden}for(const fx of AMEffectGPU.effects(l))if(!AMEffectDefinitions[fx.id]&&!OMSAMComplex.nativeEffects.has(fx.id))scene.project.amWarnings.push('Efek belum didukung: '+fx.id)}for(const l of scene.layers)if(l.type==='text'&&l.amImport.font.startsWith('imported?'))scene.project.amWarnings.push('Font asli diperlukan: '+l.fontFamily);scene.project.amWarnings=[...new Set(scene.project.amWarnings)];return scene};
