    this.el('exportResultSave')?.addEventListener('click',()=>this.save());
    this.el('exportResultShare')?.addEventListener('click',()=>this.share());
    this.el('exportResultClose')?.addEventListener('click',()=>this.close());
    this.el('exportResultBackTop')?.addEventListener('click',()=>this.close());
    play?.addEventListener('click',()=>this.togglePlayback());
    fullscreen?.addEventListener('click',()=>this.toggleFullscreen());
    document.addEventListener('fullscreenchange',()=>this.onFullscreenChange());
    document.addEventListener('webkitfullscreenchange',()=>this.onFullscreenChange());
    const stage=this.el('exportResultStage'),controls=stage?.querySelector('.exportResultControls');
    // Desktop: controls appear only after pointer movement. Mobile/coarse pointer: a touch reveals them.
    stage?.addEventListener('pointermove',e=>{
      if(!this.isFullscreen()||e.pointerType==='touch'||controls?.contains(e.target))return;
      this.fullscreenPointerCoarse=false;this.revealFullscreenUi({autoHide:true});
    },{passive:true});
