    controls?.addEventListener('pointerup',()=>{if(this.isFullscreen())this.scheduleFullscreenUiHide()},{passive:true});
    video?.addEventListener('click',()=>{if(this.isFullscreen()&&this.suppressNextFullscreenVideoClick){this.suppressNextFullscreenVideoClick=false;return}this.togglePlayback()});
    video?.addEventListener('play',()=>{this.refreshPlayButton();this.startTimelineLoop();this.startAmbientLoop()});
    video?.addEventListener('pause',()=>{this.refreshPlayButton();this.stopTimelineLoop();this.stopAmbientLoop();this.refreshTimeline();this.captureAmbient({quick:false})});
    video?.addEventListener('ended',()=>{this.refreshPlayButton();this.stopTimelineLoop();this.stopAmbientLoop();this.refreshTimeline();this.captureAmbient({quick:false})});
    video?.addEventListener('loadedmetadata',()=>{this.refreshTimeline();this.captureAmbient({quick:true,initial:true})});
    video?.addEventListener('loadeddata',()=>this.captureAmbient({quick:true,initial:true}));
    video?.addEventListener('seeked',()=>this.captureAmbient({quick:true}));
    video?.addEventListener('durationchange',()=>this.refreshTimeline());
    video?.addEventListener('timeupdate',()=>{if(!this.scrubbing)this.refreshTimeline()});
    video?.addEventListener('error',()=>{
      const meta=this.el('exportResultMeta');
      if(meta&&this.blob)meta.textContent='Preview tidak dapat diputar di browser ini • file tetap dapat disimpan';
    });
    seek?.addEventListener('pointerdown',()=>{this.scrubbing=true;if(this.isFullscreen())this.revealFullscreenUi({autoHide:false})});
    seek?.addEventListener('pointerup',()=>{this.scrubbing=false;this.seekFromControl();if(this.isFullscreen())this.scheduleFullscreenUiHide()});
    seek?.addEventListener('change',()=>{this.scrubbing=false;this.seekFromControl();if(this.isFullscreen())this.scheduleFullscreenUiHide()});
    seek?.addEventListener('input',()=>this.seekFromControl(true));
