    const copy=document.createElement('button');copy.textContent='Salin Diagnostik';copy.style.cssText='border:0;border-radius:9px;padding:9px 12px;background:#00d7a7;color:#07120f;font-weight:800';copy.onclick=()=>{const label=copy.textContent,text=this.gpuDiagnosticText();copy.disabled=true;omsCopyTextToClipboard(text).then(result=>{copy.textContent=result.ok?'Tersalin':'Gagal Salin';if(result.ok)omsDiagnostics.log('ui','GPU_DIAGNOSTIC_CLIPBOARD_COPY',result.method,{chars:text.length},{force:true});else pre.textContent=text}).catch(()=>{copy.textContent='Gagal Salin'}).finally(()=>{setTimeout(()=>{copy.textContent=label;copy.disabled=false},1400)})};
    const close=document.createElement('button');close.textContent='Tutup';close.style.cssText='border:1px solid #46506f;border-radius:9px;padding:9px 12px;background:#242a3d;color:#fff;font-weight:700';close.onclick=()=>wrap.remove();
