      let done=false;
      const finish=event=>{if(done)return;done=true;clearTimeout(timer);el.removeEventListener(type,finish);resolve({event:type,triggered:!!event,timeout:!event,elapsedMs:OMSDecoderDiagnostics.finite(performance.now()-started)})};
