        v.src=state.src||l.dataUrl||'';v.preload='auto';v.muted=state.muted;v.volume=state.volume;v.playbackRate=state.rate;v.load();
        const seek=()=>{try{const map=mediaClipMap(l,model.time);v.currentTime=Math.max(0,Number.isFinite(map.mediaTime)?map.mediaTime:state.time)}catch(e){};if(typeof l.startVideoFramePump==='function'&&!l.frameRequestId&&!l._sharedVideoLeaderId){try{l.startVideoFramePump()}catch(e){}}};
