function canvasPointFromClient(clientX,clientY,rect){
  return {
    x:(clientX-rect.left)*(renderer.canvas.width/rect.width),
    y:(clientY-rect.top)*(renderer.canvas.height/rect.height)
  };
}

function canvasPoint(e){
  const p=latestPointerSample(e);
  const r=renderer.canvas.getBoundingClientRect();
  return canvasPointFromClient(p.clientX,p.clientY,r);
}

renderer.canvas.addEventListener('pointerdown',e=>{
  const sample=latestPointerSample(e);
  const rect=renderer.canvas.getBoundingClientRect();
  const p=canvasPointFromClient(sample.clientX,sample.clientY,rect);
  const l=renderer.hitTest(p.x,p.y);

  if(!l){
    renderer.endInteraction();
    model.selected=null;
    timeline.rebuild();
    renderer.render();
    return;
  }

  model.selected=l.id;
  history.push();
  model.drag={
    p,
    x:model.prop(l,'x'),
    y:model.prop(l,'y'),
    drag3d:renderer.dragContext?.(l,p.x,p.y)||null,
    rect,
    pointerId:e.pointerId
  };

  renderer.beginInteraction(l.id);
  renderer.canvas.setPointerCapture(e.pointerId);
  timeline.rebuild();
  ui.openInspectorRoot();
  renderer.render();
});

renderer.canvas.addEventListener('pointermove',e=>{
  const g=model.drag;
  if(!g)return;

  const l=model.selectedLayer();
  if(!l||l.locked)return;

  const sample=latestPointerSample(e);
  const clientX=sample.clientX,clientY=sample.clientY;

  interaction.schedule('canvas-layer-drag',()=>{
    if(!model.drag)return;
    const p=canvasPointFromClient(clientX,clientY,g.rect);
    const worldDrag=g.drag3d&&renderer.dragPosition?.(l,p.x,p.y,g.drag3d);
    if(worldDrag){ui.setTransformValue(l,'x',worldDrag.x);ui.setTransformValue(l,'y',worldDrag.y)}
    else{const dx=p.x-g.p.x,dy=p.y-g.p.y;ui.setTransformValue(l,'x',g.x+dx);ui.setTransformValue(l,'y',g.y+dy)}
  });
});

const finishCanvasDrag=()=>{
  interaction.flushNow('canvas-layer-drag');
  model.drag=null;
  renderer.endInteraction();
  renderer.render();
};

renderer.canvas.addEventListener('pointerup',finishCanvasDrag);
renderer.canvas.addEventListener('pointercancel',finishCanvasDrag);

const homeFab=$('#newProjectFab');
let homeFabOpenedAt=0;

const openNewProjectModal=e=>{
  e?.preventDefault?.();
  e?.stopPropagation?.();

  // pointerdown + click can both fire from one tap; debounce them.
  const now=performance.now();
  if(now-homeFabOpenedAt<220)return;
  homeFabOpenedAt=now;

  const modal=$('#newModal');
  if(modal){
    modal.classList.remove('hidden');
    homeFab.style.display='none';
    homeFab.style.pointerEvents='none';
  }
};

