function getShortcutTr(key) {
  if (typeof OMS_SHORTCUT_I18N === 'undefined' || !OMS_SHORTCUT_I18N) return key;
  const lang = (typeof homeLanguage !== 'undefined' && homeLanguage) ? homeLanguage : 'en';
  return OMS_SHORTCUT_I18N[lang]?.[key] ?? OMS_SHORTCUT_I18N.en?.[key] ?? OMS_SHORTCUT_I18N.id?.[key] ?? key;
}

var activeShortcuts = (() => {
  try {
    const saved = localStorage.getItem('oms_keyboard_shortcuts');
    if (saved) {
      const parsed = JSON.parse(saved);
      return normalizeSavedShortcuts283(parsed);
    }
  } catch(e) {}
  return JSON.parse(JSON.stringify(OMS_DEFAULT_SHORTCUTS));
})();

// Local integration of PR33 by anonimBRO-design. Keep its actions/translations,
// but never let malformed persisted data create commands or inject UI markup.
function normalizeSavedShortcuts283(parsed) {
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) throw Error('Invalid shortcut settings');
  const out=JSON.parse(JSON.stringify(OMS_DEFAULT_SHORTCUTS)),seen=new Set();
  for (const id of Object.keys(out)) {
    const saved=parsed[id];
    if (saved !== undefined) {
      if (!saved || typeof saved !== 'object' || !/^[A-Za-z][A-Za-z0-9]{0,39}$/.test(saved.code || '') || ['ControlLeft','ControlRight','AltLeft','AltRight','ShiftLeft','ShiftRight','MetaLeft','MetaRight','Escape','Unidentified'].includes(saved.code) || !['ctrl','shift','alt'].every(k=>typeof saved[k]==='boolean')) throw Error('Invalid shortcut '+id);
      out[id]={...out[id],code:saved.code,ctrl:saved.ctrl,shift:saved.shift,alt:saved.alt};
    }
    const s=out[id],signature=[s.code.toLowerCase(),s.ctrl,s.shift,s.alt].join(':');
    if (seen.has(signature) || id!=='help'&&s.code==='Slash'&&s.shift&&!s.ctrl&&!s.alt) throw Error('Conflicting saved shortcuts');
    seen.add(signature);
  }
  return out;
}
var shortcutsReturnFocus283=null;
var remapReturnFocus283=null;

function formatShortcutKey(s) {
  const parts = [];
  if (s.ctrl) parts.push(navigator.platform?.includes('Mac') ? 'Cmd' : 'Ctrl');
  if (s.alt) parts.push('Alt');
  if (s.shift) parts.push('Shift');
  let name = s.code || s.key || '';
  if (name.startsWith('Key')) name = name.slice(3);
  else if (name.startsWith('Digit')) name = name.slice(5);
  else if (name === 'ArrowLeft') name = '←';
  else if (name === 'ArrowRight') name = '→';
  else if (name === 'ArrowUp') name = '↑';
  else if (name === 'ArrowDown') name = '↓';
  else if (name === 'Space') name = 'Space';
  else if (name === 'Delete') name = 'Del';
  parts.push(name);
  return parts;
}

function renderShortcutsList() {
  if (typeof activeShortcuts === 'undefined' || !activeShortcuts) return;
  const container = $('#shortcutsList');
  if (!container) return;
  const categories = [
    { id: 'playback', titleKey: 'category_playback' },
    { id: 'timeline', titleKey: 'category_timeline' },
    { id: 'editing', titleKey: 'category_editing' },
    { id: 'general', titleKey: 'category_general' }
  ];

  let html = '';
  for (const cat of categories) {
    const catActions = Object.entries(activeShortcuts).filter(([k, v]) => v.category === cat.id);
    if (!catActions.length) continue;
    html += `<div class="shortcutCategoryBlock">
      <div class="shortcutCategoryTitle">${getShortcutTr(cat.titleKey)}</div>`;
    for (const [actionId, sc] of catActions) {
      const label = getShortcutTr(`act_${actionId}`);
      const keyParts = formatShortcutKey(sc);
      const kbdHtml = keyParts.map(k => `<kbd class="shortcutKbd">${esc(k)}</kbd>`).join(' + ');
      html += `<div class="shortcutRow" data-action="${actionId}">
        <span class="shortcutRowLabel">${label}</span>
        <div class="shortcutRowRight">
          <div class="shortcutKbdWrap">${kbdHtml}</div>
          <button type="button" class="shortcutEditBtn" data-edit-action="${actionId}" title="${getShortcutTr('remapTitle')}" aria-label="${getShortcutTr('remapTitle')}">✎</button>
        </div>
      </div>`;
    }
    html += `</div>`;
  }
  container.innerHTML = html;

  container.querySelectorAll('[data-edit-action]').forEach(btn => {
    btn.onclick = () => openRemapModal(btn.dataset.editAction);
  });

  const titleEl = $('#shortcutsModalTitle');
  if (titleEl) titleEl.textContent = getShortcutTr('modalTitle');
  const subEl = $('#shortcutsModalSubtitle');
  if (subEl) subEl.textContent = getShortcutTr('modalSubtitle');
  const resetBtn = $('#resetShortcutsBtn');
  if (resetBtn) resetBtn.textContent = getShortcutTr('resetBtn');
  const doneBtn = $('#doneShortcutsBtn');
  if (doneBtn) doneBtn.textContent = getShortcutTr('doneBtn');
}

function openShortcutsModal() {
  shortcutsReturnFocus283=document.activeElement;
  renderShortcutsList();
  $('#shortcutsModal')?.classList.remove('hidden');
  $('#closeShortcutsModal')?.focus({preventScroll:true});
}

function closeShortcutsModal() {
  closeRemapModal();
  $('#shortcutsModal')?.classList.add('hidden');
  if(shortcutsReturnFocus283?.isConnected)shortcutsReturnFocus283.focus({preventScroll:true});
}

function toggleShortcutsModal() {
  const modal = $('#shortcutsModal');
  if (!modal) return;
  modal.classList.contains('hidden') ? openShortcutsModal() : closeShortcutsModal();
}

var currentRemapAction = null;
var pendingKeyCombo = null;

function openRemapModal(actionId) {
  if(!Object.hasOwn(OMS_DEFAULT_SHORTCUTS,actionId))return;
  remapReturnFocus283=document.activeElement;
  currentRemapAction = actionId;
  pendingKeyCombo = null;
  const remapModal = $('#shortcutRemapModal');
  if (!remapModal) return;
  const titleEl = $('#remapActionTitle');
  if (titleEl) titleEl.textContent = `${getShortcutTr('remapTitle')}: ${getShortcutTr(`act_${actionId}`)}`;
  const promptEl = $('#remapPromptText');
  if (promptEl) promptEl.textContent = getShortcutTr('remapPrompt');
  const keyDisplay = $('#remapKeyDisplay');
  if (keyDisplay) keyDisplay.innerHTML = `<kbd class="shortcutKbd">${getShortcutTr('remapPrompt')}</kbd>`;
  const warnEl = $('#remapConflictText');
  if (warnEl) {
    warnEl.textContent = '';
    warnEl.classList.add('hidden');
  }
  const saveBtn = $('#saveRemapBtn');
  if (saveBtn) {
    saveBtn.disabled = true;
    saveBtn.textContent = getShortcutTr('saveBtn');
  }
  const cancelBtn = $('#cancelRemapBtn');
  if (cancelBtn) cancelBtn.textContent = getShortcutTr('cancelBtn');
  remapModal.classList.remove('hidden');
  $('#cancelRemapBtn')?.focus({preventScroll:true});
}

function closeRemapModal() {
  $('#shortcutRemapModal')?.classList.add('hidden');
  currentRemapAction = null;
  pendingKeyCombo = null;
  if(remapReturnFocus283?.isConnected)remapReturnFocus283.focus({preventScroll:true});
}

function checkShortcutConflict(combo, actionId) {
  if(actionId!=='help'&&combo.code==='Slash'&&combo.shift&&!combo.ctrl&&!combo.alt)return 'help';
  for (const [otherId, s] of Object.entries(activeShortcuts)) {
    if (otherId === actionId) continue;
    if (s.ctrl === combo.ctrl && s.shift === combo.shift && s.alt === combo.alt && String(s.code).toLowerCase() === String(combo.code).toLowerCase()) {
      return otherId;
    }
  }
  return null;
}

window.addEventListener('keydown', e => {
  const remapModal = $('#shortcutRemapModal');
  if (!remapModal || remapModal.classList.contains('hidden')) return;
  e.preventDefault();
  e.stopPropagation();
  if(e.isComposing || e.keyCode===229)return;

  if (e.key === 'Escape') {
    closeRemapModal();
    return;
  }

  const isModifier = ['Control', 'Shift', 'Alt', 'Meta'].includes(e.key);
  const ctrl = !!(e.ctrlKey || e.metaKey);
  const shift = !!e.shiftKey;
  const alt = !!e.altKey;

  if (isModifier) {
    const mods = [];
    if (ctrl) mods.push(navigator.platform?.includes('Mac') ? 'Cmd' : 'Ctrl');
    if (alt) mods.push('Alt');
    if (shift) mods.push('Shift');
    const keyDisplay = $('#remapKeyDisplay');
    if (keyDisplay) keyDisplay.innerHTML = mods.map(m => `<kbd class="shortcutKbd">${m}</kbd>`).join(' + ') + ' + ...';
    const saveBtn = $('#saveRemapBtn');
    if (saveBtn) saveBtn.disabled = true;
    return;
  }

  const code = e.code || e.key;
  if(!/^[A-Za-z][A-Za-z0-9]{0,39}$/.test(code)||code==='Unidentified')return;
  const combo = { code, ctrl, shift, alt };
  pendingKeyCombo = combo;

  const keyDisplay = $('#remapKeyDisplay');
  if (keyDisplay) {
    const keyParts = formatShortcutKey(combo);
    keyDisplay.innerHTML = keyParts.map(k => `<kbd class="shortcutKbd">${esc(k)}</kbd>`).join(' + ');
  }

  const conflictAction = checkShortcutConflict(combo, currentRemapAction);
  const warnEl = $('#remapConflictText');
  const saveBtn = $('#saveRemapBtn');

  if (conflictAction) {
    const conflictName = getShortcutTr(`act_${conflictAction}`);
    if (warnEl) {
      warnEl.textContent = getShortcutTr('conflictWarning').replace('{action}', conflictName);
      warnEl.classList.remove('hidden');
    }
    if (saveBtn) saveBtn.disabled = true;
  } else {
    if (warnEl) warnEl.classList.add('hidden');
    if (saveBtn) saveBtn.disabled = false;
  }
}, true);

$('#saveRemapBtn')?.addEventListener('click', () => {
  if (currentRemapAction && pendingKeyCombo && !$('#saveRemapBtn')?.disabled) {
    activeShortcuts[currentRemapAction] = {
      ...activeShortcuts[currentRemapAction],
      code: pendingKeyCombo.code,
      ctrl: pendingKeyCombo.ctrl,
      shift: pendingKeyCombo.shift,
      alt: pendingKeyCombo.alt
    };
    try {
      localStorage.setItem('oms_keyboard_shortcuts', JSON.stringify(activeShortcuts));
    } catch(e) {}
    toast(getShortcutTr('toastSaved'));
    closeRemapModal();
    renderShortcutsList();
  }
});

$('#cancelRemapBtn')?.addEventListener('click', closeRemapModal);
$('#closeRemapModal')?.addEventListener('click', closeRemapModal);
$('#shortcutRemapModal')?.addEventListener('click', e => {
  if (e.target === $('#shortcutRemapModal')) closeRemapModal();
});

$('#resetShortcutsBtn')?.addEventListener('click', () => {
  activeShortcuts = JSON.parse(JSON.stringify(OMS_DEFAULT_SHORTCUTS));
  try {
    localStorage.removeItem('oms_keyboard_shortcuts');
  } catch(e) {}
  toast(getShortcutTr('toastReset'));
  renderShortcutsList();
});

$('#doneShortcutsBtn')?.addEventListener('click', closeShortcutsModal);
$('#closeShortcutsModal')?.addEventListener('click', closeShortcutsModal);
$('#shortcutsModal')?.addEventListener('click', e => {
  if (e.target === $('#shortcutsModal')) closeShortcutsModal();
});
$('#shortcutsHelpBtn')?.addEventListener('click', openShortcutsModal);

function executeShortcutAction(actionId) {
  if (actionId === 'help') {
    toggleShortcutsModal();
    return true;
  }
  if (actionId==='delete'&&ui.projectSelectionActive?.()) {
    ui.deleteSelectedProjects();
    return true;
  }
  if ($('#editor').classList.contains('hidden') || !model.project) {
    return false;
  }
  const fps = Number(model.project.fps) || 30;
  const workspace=window.omsGroupWorkspace;
  const start=workspace?.current?.()?workspace.start():0;
  const end=workspace?.current?.()?workspace.end():Math.max(0,Number(model.project.duration ?? model.project.dur)||0);
  const frameStep = 1 / fps;

  function doSeek(target) {
    clock.stop({continuePreRender:false});
    const clamped = Math.max(start, Math.min(end, target));
    model.time = timeline.snapTime ? timeline.snapTime(clamped) : clamped;
    timeline.updatePlayhead();
    const pre = window.omsTimelinePreRender;
    pre?.settleTraversal?.(model.time, 1200);
    const cached = pre?.tryShowAt?.(model.time, {scrub: true}) || false;
    if (!cached) pre?.requestSettledGapFill?.(model.time);
    media?.sync?.(model.time, false, false, {forceSeek: true, interactiveScrub: false, preserveFrameCache: false});
    if (!cached && !timeline.hasActiveScrubVideo?.(model.time)) renderer.render();
  }

  switch(actionId) {
    case 'playPause':
      clock.toggle();
      return true;
    case 'stepBack1':
      doSeek(model.time - frameStep);
      return true;
    case 'stepForward1':
      doSeek(model.time + frameStep);
      return true;
    case 'stepBack10':
      doSeek(model.time - 10 * frameStep);
      return true;
    case 'stepForward10':
      doSeek(model.time + 10 * frameStep);
      return true;
    case 'goToStart':
      doSeek(start);
      return true;
    case 'goToEnd':
      doSeek(end);
      return true;
    case 'undo':
      ui.undoAction();
      return true;
    case 'redo':
      ui.redoAction();
      return true;
    case 'save':
      ui.saveLocal();
      return true;
    case 'duplicate':
      if (model.selected) {
        ui.duplicateSelectedLayer?.();
      }
      return true;
    case 'delete':
      if (ui.projectSelectionActive?.()) {
        ui.deleteSelectedProjects();
      } else if (model.selected) {
        history.push();
        model.removeLayer(model.selected);
        ui.rebuildAll();
      }
      return true;
    default:
      return false;
  }
}

function matchesShortcutEvent(e, s) {
  if (!s) return false;
  const isCtrl = !!(e.ctrlKey || e.metaKey);
  const isShift = !!e.shiftKey;
  const isAlt = !!e.altKey;
  if (isCtrl !== !!s.ctrl || isShift !== !!s.shift || isAlt !== !!s.alt) return false;

  const targetCode = s.code || s.key || '';
  if (e.code) return e.code.toLowerCase() === targetCode.toLowerCase();
  if (e.key && e.key.toLowerCase() === targetCode.toLowerCase()) return true;
  if (targetCode.startsWith('Key') && e.code === targetCode) return true;
  if (targetCode.startsWith('Key') && e.key && e.key.toUpperCase() === targetCode.slice(3).toUpperCase()) return true;
  return false;
}

document.addEventListener('keydown', e => {
  if(e.isComposing || e.keyCode===229)return;
  const tag = document.activeElement?.tagName;
  if (['INPUT', 'SELECT', 'TEXTAREA'].includes(tag)||document.activeElement?.isContentEditable||e.target?.isContentEditable) return;
  if (!$('#shortcutRemapModal')?.classList.contains('hidden')) return;

  if (e.key === 'Escape') {
    if (!$('#shortcutsModal')?.classList.contains('hidden')) {
      e.preventDefault();
      closeShortcutsModal();
      return;
    }
    if (ui.projectSelectionActive?.()) {
      e.preventDefault();
      ui.exitProjectSelection();
      return;
    }
  }

  // Secondary trigger for shortcuts guide: ? or F1
  if ((e.key === '?' || (e.shiftKey && e.code === 'Slash')) && !e.ctrlKey && !e.altKey && !e.metaKey) {
    e.preventDefault();
    if(e.repeat)return;
    toggleShortcutsModal();
    return;
  }

  // Match against active configurable shortcuts
  if(!$('#shortcutsModal')?.classList.contains('hidden')){
    if(matchesShortcutEvent(e,activeShortcuts.help)){e.preventDefault();closeShortcutsModal();}
    else if(e.key==='Tab'){
      const items=[...$('#shortcutsModal').querySelectorAll('button:not(:disabled)')].filter(n=>n.getClientRects().length),first=items[0],last=items.at(-1);
      if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}
      else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}
    }else if(!['Space','Enter'].includes(e.code)||document.activeElement?.tagName!=='BUTTON')e.preventDefault();
    return;
  }
  if(document.activeElement?.closest?.('button,[role="button"]')&&['Space','Enter'].includes(e.code))return;
  for (const [actionId, sc] of Object.entries(activeShortcuts)) {
    if (matchesShortcutEvent(e, sc)) {
      if(e.repeat&&!actionId.startsWith('step')){e.preventDefault();return;}
      if(executeShortcutAction(actionId))e.preventDefault();
      return;
    }
  }

  // Secondary fallbacks for natural keyboard habits
  if (e.key === 'Backspace' && !e.ctrlKey && !e.shiftKey && !e.altKey) {
    if (executeShortcutAction('delete')) e.preventDefault();
  } else if ((e.ctrlKey || e.metaKey) && !e.shiftKey && !e.altKey && e.code === 'KeyY') {
    if (executeShortcutAction('redo')) e.preventDefault();
  }
});
window.omsShortcutsInitialized = true;
renderShortcutsList();
const helpBtn = $('#shortcutsHelpBtn');
if (helpBtn && typeof getShortcutTr === 'function') helpBtn.title = getShortcutTr('modalTitle') + ' (F1 / ?)';
window.omsKeyboardShortcuts={open:openShortcutsModal,close:closeShortcutsModal,bindings:()=>JSON.parse(JSON.stringify(activeShortcuts)),defaults:()=>JSON.parse(JSON.stringify(OMS_DEFAULT_SHORTCUTS)),languages:()=>Object.keys(OMS_SHORTCUT_I18N),version:283,contribution:'https://github.com/Hada45/Open-Motion/pull/33',author:'anonimBRO-design'};

