const APP_TEXT_LOOKUP={};
for(const pack of Object.values(APP_UI_I18N)){
  for(const [key,val] of Object.entries(pack||{})){
    if(typeof val==='string'&&val.trim())APP_TEXT_LOOKUP[val.trim()]=key;
  }
}
const APP_EXTRA_TEXT_KEYMAP={
  'Warna & Fill':'colorFill','Color & Fill':'colorFill',
  'Color & Fill':'colorFill','Ruang 3D':'space3d','3D Space':'space3d',
  'Kamera 3D penuh':'full3dCamera','Full 3D Camera':'full3dCamera',
  'Project & Environment':'projectEnvironment','Nama':'nameField','Name':'nameField',
  'Background':'background','Grid Dunia 3D':'world3dGrid','3D World Grid':'world3dGrid',
  'Playhead':'playhead','Tetap di Tengah':'stayCentered','Stay Centered':'stayCentered',
  'Bergerak (Mode Lama)':'movingLegacy','Moving (Legacy Mode)':'movingLegacy',
  'Kecepatan':'speed','Speed':'speedWord','Vol':'volumeShort'
};
Object.assign(APP_TEXT_LOOKUP,APP_EXTRA_TEXT_KEYMAP);
function appTr(key){
  const pack=APP_UI_I18N[homeLanguage]||APP_UI_I18N.en||APP_UI_I18N.id;
  return pack?.[key]??APP_UI_I18N.en?.[key]??APP_UI_I18N.id?.[key]??HOME_I18N[homeLanguage]?.[key]??HOME_I18N.en?.[key]??HOME_I18N.id?.[key]??key;
}
function translateExactTextNode(node){
  if(!node||!node.nodeValue)return;
  const raw=node.nodeValue;
  const trimmed=raw.trim();
  if(!trimmed)return;
  const key=APP_TEXT_LOOKUP[trimmed];
  if(!key)return;
  const next=appTr(key);
  if(!next||next===trimmed)return;
  const lead=(raw.match(/^\s*/)||[''])[0];
  const trail=(raw.match(/\s*$/)||[''])[0];
  node.nodeValue=lead+next+trail;
}
function translateTextTree(root=document.body){
  if(!root)return;
  const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode(node){
    if(!node||!node.parentElement)return NodeFilter.FILTER_REJECT;
    const p=node.parentElement;
    if(['SCRIPT','STYLE'].includes(p.tagName))return NodeFilter.FILTER_REJECT;
    if(p.closest('.trackName,.projectMeta'))return NodeFilter.FILTER_REJECT;
    const t=node.nodeValue?.trim();
    return t&&APP_TEXT_LOOKUP[t]?NodeFilter.FILTER_ACCEPT:NodeFilter.FILTER_REJECT;
  }});
  const nodes=[];let n;
  while(n=walker.nextNode())nodes.push(n);
  nodes.forEach(translateExactTextNode);
}
function applyWholeAppLanguage(){
  const setValueIfDefault=(selector,key,defaults)=>{const el=$(selector);if(!el)return;const val=(el.value||'').trim();if(!val||defaults.includes(val))el.value=appTr(key)};
  if($('#toggle3d'))$('#toggle3d').title=appTr('space3d');
  if($('#cameraView'))$('#cameraView').title=appTr('viewThroughCamera');
  setValueIfDefault('#newName','projectNewName',['Project Baru','Proyek Baru','NEW PROJECT','New Project','新建项目','新規プロジェクト','Projek Baharu','โปรเจกต์ใหม่','Dự án mới','Bagong Proyekto','Projetu Foun','Novo Projeto','புதிய திட்டம்']);
  translateTextTree(document.body);
  applyExperimentalNoticeLanguage();
}
