    const project=model.project;if(!layers.length){toast('Media proyek tersedia.');return}
    const d=document.createElement('dialog');d.className='amDialog';d.style.cssText='width:480px;max-width:90vw;background:#171c27;color:white;padding:24px;border:1px solid #65d4c9;border-radius:14px';
    const title=document.createElement('h3');title.textContent='Pulihkan media proyek lama';
    const note=document.createElement('p');note.textContent=`${layers.length} layer media belum dapat dibuka. Layer, keyframe, efek dan potongan waktu tidak akan diganti.`;
    const info=document.createElement('p');info.textContent=project?.amShareLink?`Ambil ulang hanya media dari AM Link asal melalui ${project.amLinkResolver==='zervida'?'API pihak ketiga':'resolver Open Motion (5 MB)'}. Memerlukan internet.`:'Tidak ada AM Link asal. Pilih layer lalu gunakan Tautkan Ulang Media untuk mencari file asli.';
    const status=document.createElement('p');status.setAttribute('role','status');
