    const close=document.createElement('button');close.textContent='Nanti';close.style.marginLeft='10px';
    close.onclick=()=>{if(!recoveryBusy){d.close();d.remove()}};d.oncancel=e=>{if(recoveryBusy)e.preventDefault();else d.remove()};
