  const MEDIA_TYPES=new Set(['image','video','audio']);
  const isMedia=l=>!!l&&MEDIA_TYPES.has(l.type);
  const selectedMedia=()=>{
    try{return model.selectedLayer?.() || (model.layers||[]).find(x=>x.id===model.selected) || null}
    catch(e){return null}
  };
  const registrySource=l=>{
    try{return l?.assetId ? mediaAssets.sources.get(l.assetId) : null}catch(e){return null}
  };
  const say=msg=>{try{toast(msg)}catch(e){try{console.log(msg)}catch(_){}}};

