    fractal_noise:`vec4 c=fetch(q);vec2 p=rotation(p_rotation*PI/180.)*(metric(q-.5)/max(.0001,p_scale))+vec2(p_offsetX,p_offsetY);float sum=0.,weight=0.,amp=1.;for(int i=0;i<4;i++){float octave=clamp(p_complexity-float(i),0.,1.);sum+=noise(p+vec2(p_evolution*.13,p_evolution*.071))*amp*octave;weight+=amp*octave;p*=max(1.,p_subScaling);amp*=p_subInfluence;}float n=clamp((sum/max(.0001,weight)-.5)*p_contrast+.5+p_brightness,0.,1.);if(p_invert>.5)n=1.-n;float alpha=(p_fitAlpha>.5?c.a:inside(q))*p_opacity;outColor=vec4(vec3(n),alpha);`,
