// BEGIN_OMS_EXPRESSION_MARKERS_V211
const OMSExpressionMarkers=(()=>{
  const field='expressionMarkers',max=128;
  const owner=(l,comp)=>comp?model.project:l;
  function rows(l,comp=false){return OMSExpressionAE.markerRows(owner(l,comp),comp)}
  function commit(l,comp,change){
    if(!model.project||!comp&&(!l||l.locked))throw Error('Layer tidak tersedia atau terkunci.');
    const o=owner(l,comp),before=Array.isArray(o[field])?o[field]:[],next=change(before.map(m=>({...m})));
    if(next.length>max)throw Error('Maksimal 128 marker.');
    history.push();o[field]=next.sort((a,b)=>a.t-b.t);OMSExpressionEffects.clear();
    try{timelinePreRender.invalidate('expression-marker')}catch(e){}
    editorInvalidation.requestRender('expression-marker');bus.emit('model:changed');return o[field];
  }
  function payload(l,comp,time,comment,duration=0){
    if(!Number.isFinite(time)||!Number.isFinite(duration)||duration<0)throw Error('Waktu/durasi marker tidak valid.');
    const o=owner(l,comp),start=comp?0:Number(o.start)||0,end=start+(Number(o.duration)||0);
    if(time<start-1e-8||time>end+1e-8)throw Error('Marker harus berada di dalam durasi layer/komposisi.');
    const fps=Math.max(1,Number(model.project?.fps)||30),snapped=Math.round(time*fps)/fps;
    return {t:Math.max(0,Math.min(end-start,snapped-start)),comment:String(comment||'').slice(0,256),duration:Math.min(duration,Math.max(0,end-time))};
  }
  function add(l,time=model.time,comment='',comp=false){const m={id:uid('marker'),...payload(l,comp,time,comment)};commit(l,comp,a=>{a.push(m);return a});return m}
  function edit(l,id,time,comment,duration=0,comp=false){const data=payload(l,comp,time,comment,duration);commit(l,comp,a=>{const m=a.find(m=>m.id===id);if(!m)throw Error('Marker tidak ditemukan.');Object.assign(m,data);return a})}
  function remove(l,id,comp=false){commit(l,comp,a=>{if(!a.some(m=>m.id===id))throw Error('Marker tidak ditemukan.');return a.filter(m=>m.id!==id)})}
  return Object.freeze({rows,add,edit,remove,max});
})();
window.omsExpressionMarkers=OMSExpressionMarkers;
(()=>{
  const html=ui.effectInstanceHTML,bind=ui.bindEffectStack;
  const panel=(l,comp=false)=>{
    const ms=OMSExpressionMarkers.rows(l,comp),fps=Math.max(1,Number(model.project?.fps)||30);
    return `<section class="omsExprMarkerSection" data-expression-markers="${comp?'comp':'layer'}"><div class="omsExprMarkerHeading"><span>${comp?'Marker komposisi':'Marker layer'} <small>${ms.length}/128</small></span><button type="button" data-marker-add ${!comp&&l.locked?'disabled':''}>＋ di playhead</button></div><p class="omsExprMarkerHint">${comp?'thisComp.marker':'marker / thisLayer.marker'} · Waktu dalam detik komposisi.${comp?'':' Marker mengikuti perpindahan awal layer.'}</p><div class="omsExprMarkerList">${ms.length?ms.map((m,i)=>`<div class="omsExprMarkerRow" data-marker-id="${esc(m.id)}"><button type="button" data-marker-seek title="Pergi ke marker">${i+1}</button><label>Waktu<input data-marker-time type="number" step="${1/fps}" value="${Number(m.time.toFixed(6))}" aria-label="Waktu marker ${i+1}"></label><label>Nama<input data-marker-comment maxlength="256" value="${esc(m.comment||'')}" aria-label="Nama marker ${i+1}"></label><button type="button" data-marker-remove aria-label="Hapus marker ${i+1}">×</button></div>`).join(''):'<p class="omsExprMarkerEmpty">Belum ada marker. Screen Shake berbasis marker baru bergerak setelah sebuah marker.</p>'}</div><output class="omsExprMarkerError" role="status"></output></section>`;
  };
  ui.effectInstanceHTML=function(l,inst){
    let result=html.call(this,l,inst);if(inst?.specId!=='expression')return result;
    const start='<details class="omsExprHelp">';
    return result.replace(start,`<details class="omsExprMarkers"><summary>Marker layer &amp; komposisi</summary>${panel(l)}${panel(l,true)}</details>`+start);
  };
  const reopen=()=>{
    const open=new Set([...document.querySelectorAll('.effectCard .omsExprMarkers[open]')].map(d=>d.closest('.effectCard').dataset.effectInstance));
    timeline.rebuild();ui.openInspector('effects');
    document.querySelectorAll('.effectCard .omsExprMarkers').forEach(d=>{d.open=open.has(d.closest('.effectCard').dataset.effectInstance)});
    renderer.render();
  };
  ui.bindEffectStack=function(l){
    const result=bind.call(this,l);
    document.querySelectorAll('.effectCard [data-expression-markers]').forEach(section=>{
      const comp=section.dataset.expressionMarkers==='comp',status=section.querySelector('.omsExprMarkerError');
      const action=fn=>{try{fn();reopen()}catch(e){status.textContent=e.message}};
      section.querySelector('[data-marker-add]').onclick=()=>action(()=>OMSExpressionMarkers.add(l,model.time,'',comp));
      section.querySelectorAll('[data-marker-id]').forEach(row=>{
        const id=row.dataset.markerId,time=row.querySelector('[data-marker-time]'),comment=row.querySelector('[data-marker-comment]');
        const change=()=>action(()=>{const old=OMSExpressionMarkers.rows(l,comp).find(m=>m.id===id);OMSExpressionMarkers.edit(l,id,Number(time.value),comment.value,old?.duration||0,comp)});
        time.onchange=change;comment.onchange=change;
        row.querySelector('[data-marker-remove]').onclick=()=>action(()=>OMSExpressionMarkers.remove(l,id,comp));
        row.querySelector('[data-marker-seek]').onclick=()=>{
          const m=OMSExpressionMarkers.rows(l,comp).find(m=>m.id===id);if(!m)return;clock.stop();model.time=m.time;media.sync(model.time,false,false);timeline.updatePlayhead();renderer.render();ui.updateEffectLiveValues(l);
        };
      });
    });
    document.querySelectorAll('.effectCard [data-expression-apply]').forEach(button=>{
      const original=button.onclick;button.onclick=event=>{const result=original?.call(button,event);if(result===false){const output=button.closest('.effectCard').querySelector('[data-expression-status]');output?.scrollIntoView({block:'nearest'})}return result};
    });
    return result;
  };
  const rebuild=timeline.rebuild;
  function timelineMarkers(){
    document.querySelectorAll('.omsExprTimelineMarker').forEach(el=>el.remove());
    document.querySelectorAll('.track[data-layer-id]').forEach(row=>{
      const l=model.layers.find(l=>l.id===row.dataset.layerId),lane=row.querySelector('.trackLane');if(!l||!lane)return;
      for(const m of OMSExpressionMarkers.rows(l)){
        const button=document.createElement('button');button.type='button';button.className='omsExprTimelineMarker';button.dataset.markerId=m.id;button.style.left=(timeline.centerPad()+m.time*timeline.px-4)+'px';button.title=`Marker ${m.comment||''} @ ${m.time.toFixed(3)}s`;button.setAttribute('aria-label',button.title);
        button.onpointerdown=e=>e.stopPropagation();button.onclick=e=>{e.stopPropagation();clock.stop();model.selected=l.id;model.time=m.time;media.sync(model.time,false,false);timeline.updatePlayhead();renderer.render();ui.openInspector('effects')};lane.appendChild(button);
      }
    });
  }
  timeline.rebuild=function(...args){const result=rebuild.apply(this,args);timelineMarkers();return result};
  // Diagnostics retain counters only, never ASTs, project objects or per-frame logs.
  const snapshot=omsDiagnostics.snapshot;
  if(typeof snapshot==='function')omsDiagnostics.snapshot=function(...args){const result=snapshot.apply(this,args);result.expression={...OMSExpressionEffects.stats(),layerMarkers:model.layers.reduce((n,l)=>n+(l.expressionMarkers?.length||0),0),compositionMarkers:model.project?.expressionMarkers?.length||0};return result};
})();
