  single('loop_pendulum_y','Ayunan Y',rotation('p=localTime*speed*frequency*6.283185+textIndex*.5; [0,Math.sin(p)*rotationY,0];',{rotationX:0,rotationY:55,fromRotation:0}),'Huruf mengayun ke kiri dan kanan.');
  single('loop_pendulum_z','Ayunan Z',rotation('p=localTime*speed*frequency*6.283185+textIndex*.5; [0,0,Math.sin(p)*fromRotation];',{rotationX:0,rotationY:0,fromRotation:25,anchorMode:1}),'Ayunan bandul per huruf.');
  single('loop_rock_xyz','Rocking XYZ',rotation(wave),'Tilt tiga sumbu dengan fase berbeda.');
