  single('loop_rising_wave','Gelombang Naik 3D',position('p=localTime*speed*frequency*6.283185+textIndex*.5; [0,Math.sin(p)*fromY,Math.cos(p)*fromZ];',{fromY:22,fromZ:70}),'Gelombang vertikal dengan kedalaman.');
