  single('loop_alternate_flip','Flip Bergantian',rotation('t=localTime*speed; d=textIndex%2===0?1:-1; [0,(t*rotationY*d+textIndex*15)%360,0];',{rotationX:0,rotationY:75,fromRotation:0}),'Huruf ganjil dan genap berlawanan arah.');
  single('loop_ripple','Ripple XYZ',rotation('p=localTime*speed*frequency*6.283185-textIndex*.6; [Math.sin(p)*rotationX,Math.sin(p+.8)*rotationY,Math.cos(p)*fromRotation];',{rotationX:30,rotationY:25,fromRotation:8}),'Gelombang tiga sumbu berjalan ke kanan.');
  single('loop_random_phase','Tilt Acak Tetap',rotation('p=localTime*speed*frequency*6.283185+random()*6.283185; [Math.sin(p)*rotationX,Math.cos(p)*rotationY,Math.sin(p)*fromRotation];',{seed:47}),'Fase acak deterministik, hasil ekspor stabil.');
