  single('loop_cassette','Kartu Bergoyang XY',rotation('p=localTime*speed*frequency*6.283185+textIndex*.3; [Math.sin(p)*rotationX,Math.sin(p+1.570796)*rotationY,0];',{target:1,rotationX:20,rotationY:40,fromRotation:0}),'Tilt X/Y fase seperempat putaran per kata.');
