  pack('pack_word_helix','Heliks per Kata',[rotation(wave,{target:1}),position(helix,{target:1,fromX:14,fromY:22,fromZ:70}),shadow],'Kata berputar sekaligus mengikuti heliks.');
  pack('pack_line_ribbon','Pita per Baris',[rotation(wave,{target:2,rotationX:35,rotationY:10,fromRotation:0}),position(orbit,{target:2,fromX:8,fromY:18,fromZ:50}),shadow],'Baris melambai seperti pita dalam kedalaman.');
  pack('pack_float_whole','Melayang Seluruh Teks',[rotation(wave,{target:3,rotationX:12,rotationY:20,fromRotation:5}),position(orbit,{target:3,fromX:12,fromY:14,fromZ:45}),shadow],'Satu kartu teks melayang dan mengayun.');
  pack('pack_counter_spin','Dua Arah Berputar',[rotation(spin,{rotationX:0,rotationY:60,fromRotation:0,selectorEnable:1,selectorEnd:50,selectorSmoothness:0}),rotation(spin,{rotationX:0,rotationY:-60,fromRotation:0,selectorEnable:1,selectorStart:50,selectorSmoothness:0}),neon],'Dua selector terpisah berputar berlawanan arah.');
  pack('pack_color_wave','Gelombang Warna 3D',[rotation(wave),{specId:'text_animator',values:{...base,rotationX:0,rotationY:0,fromRotation:0,poseMode:2,speed:.5,animColor:1,animR:.2,animG:.7,animB:1}},style({strokeWidth:1,strokeAlpha:.4})],'Tilt kontinu dan highlight warna berfase.');
  pack('pack_depth_pulse','Depth Pulse Neon',[position('p=localTime*speed*frequency*6.283185+textIndex*.5; [0,0,Math.sin(p)*fromZ];',{fromZ:65}),motion(3,'p=localTime*speed*frequency*6.283185+textIndex*.5; [100+Math.sin(p)*(axisScaleX-100),100+Math.sin(p)*(axisScaleY-100)];',{rotationX:0,rotationY:0,fromRotation:0,axisScaleX:115,axisScaleY:115}),neon],'Kedalaman, scale pulse dan glow ringan.');
  pack('pack_carousel','Carousel Kata',[rotation(spin,{target:1,rotationX:0,rotationY:45,fromRotation:0}),position(orbit,{target:1,fromX:20,fromY:6,fromZ:80}),gold],'Kata mengorbit sambil berputar Y.');
  pack('pack_swing_shadow','Shadow Swing 3D',[rotation(wave,{target:3,rotationX:10,rotationY:16,fromRotation:6}),position(orbit,{target:3,fromX:8,fromY:12,fromZ:35}),style({strokeWidth:0,shadowAlpha:.3,shadowY:4})],'Teks satu kartu mengayun dengan bayangan lembut.');
