  if(l?.type!=='video'||!model.layers.includes(l))throw Error('Footage sumber tidak lagi berada di proyek ini.');
  if(!valid(l)||model.playing||job||renderer.exporting||exporter.running)throw Error('Hasil tracking harus siap dan playback/export harus berhenti.');
  if(l.locked||!Number.isInteger(id)||!observationAt(l,id))throw Error('Pilih satu titik + yang terlihat pada video yang tidak terkunci.');
