  for(let i=segment.first;i<=segment.last;i++){const t=tr.start+(segment.track.start+i)*tr.frameDuration;if(t>=segment.start-1e-8&&t<=segment.end+1e-8)times.push(clamp(t,segment.start,segment.end));}
