  function badges(layer) {
    const root = document.querySelector('.omsEffects239');
    if (!root) return;
    for (const card of root.querySelectorAll('.effectCard')) {
      const inst = layer.effectStack?.find(i => i.instanceId === card.dataset.effectInstance);
      if (!inst) continue;
      for (const row of card.querySelectorAll('.effectParamRow')) {
        const id = row.dataset.effectParamId, hasKeys = !!layer.kf?.[omsEffectParamPath(inst.instanceId, id)]?.length;
        const hasExpr = !!expression(inst, id);
        row.querySelector('[data-fx-key-badge]')?.classList.toggle('visible', hasKeys);
        row.querySelector('[data-fx-expression-badge]')?.classList.toggle('visible', hasExpr);
        row.classList.toggle('hasParameterExpression', hasExpr);
        row.classList.toggle('parameterExpressionError', !!errors.get(inst)?.get(id));
        const native = row.querySelector('[data-effect-param-bool],[data-effect-param-select]');
        for (const button of row.querySelectorAll('[data-fx-segment]')) {
          const active = Number(button.dataset.fxSegment) === (native?.type === 'checkbox' ? Number(native.checked) : Number(native?.value));
          button.classList.toggle('active', active); button.setAttribute('aria-pressed', String(active));
          button.disabled = !!layer.locked || !!native?.disabled;
        }
      }
    }
    const ctx = ui.effectActiveContext(layer);
    for (const button of root.querySelectorAll('[data-fx-key],[data-fx-expression]')) button.disabled = !ctx || ctx.param.readOnly || layer.locked;
    root.querySelector('[data-fx-key]')?.classList.toggle('active', !!ctx && model.anim.hasKeyAt(layer, ctx.path, model.time, .015));
    root.querySelector('[data-fx-expression]')?.classList.toggle('active', !!ctx && !!expression(ctx.inst, ctx.param.id));
  }
  const oldBind = ui.bindEffectStack;
  ui.bindEffectStack = function(layer, ...args) {
    const result = oldBind.call(this, layer, ...args), root = document.querySelector('.omsEffects239');
    if (!root) return result;
    if (layer.locked) {
      for (const control of root.querySelectorAll('[data-effect-param-number],[data-effect-param-range],[data-effect-param-ruler],[data-effect-param-bool],[data-effect-param-select],[data-effect-key],[data-effect-toggle],[data-effect-delete],[data-effect-drag],#addEffectBtn')) {
        control.disabled = true;
        if (control.hasAttribute('data-effect-param-ruler')) control.style.pointerEvents = 'none';
      }
    }
    root.querySelector('[data-fx-back]').onclick = () => { closeSurface(); this.openInspectorRoot(layer); };
    root.querySelector('[data-fx-close-drawer]').onclick = () => { closeSurface(); this.closeDrawer(); };
    root.querySelector('[data-fx-expression]').onclick = event => expressionPanel(layer, event.currentTarget);
    root.querySelector('[data-fx-more]').onclick = event => clipboardPanel(layer, event.currentTarget);
    root.querySelector('[data-fx-presets]').onclick = event => presetGallery(layer, event.currentTarget);
    root.querySelector('[data-fx-save-preset]').onclick = event => savePreset(layer, event.currentTarget);
    if (this.effectEaseEditorOpen) root.querySelector('#addEffectBtn').onclick = () => this.openEffectBrowser(layer);
    root.querySelector('[data-fx-key]').onclick = () => {
      const ctx = this.effectActiveContext(layer);
      if (ctx && !layer.locked) root.querySelector('[data-effect-instance="' + ctx.inst.instanceId + '"] [data-effect-key="' + ctx.param.id + '"]')?.click();
    };
    for (const card of root.querySelectorAll('.effectCard')) {
      const inst = layer.effectStack.find(i => i.instanceId === card.dataset.effectInstance), spec = omsEffectSpec(inst.specId);
      for (const button of card.querySelectorAll('[data-fx-open-text-presets]')) button.onclick = event => presetGallery(layer, event.currentTarget, inst);
      for (const row of card.querySelectorAll('.effectParamRow')) {
        const p = spec.params.find(p => p.id === row.dataset.effectParamId);
        if (!p) continue;
        row.querySelector('.effectParamLabel')?.addEventListener('click', () => { this.setActiveEffectParameter(layer, inst, p); badges(layer); });
        for (const button of row.querySelectorAll('[data-fx-segment]')) button.onclick = event => {
          event.preventDefault(); event.stopPropagation();
          if (layer.locked || p.readOnly) return;
          this.setActiveEffectParameter(layer, inst, p);
          const control = row.querySelector('[data-effect-param-bool],[data-effect-param-select]');
          if (control.type === 'checkbox') control.checked = Number(button.dataset.fxSegment) === 1;
          else control.value = button.dataset.fxSegment;
          control.dispatchEvent(new Event('change', {bubbles: true})); badges(layer);
        };
      }
    }
    badges(layer);
    return result;
  };
  const update = ui.updateEffectLiveValues;
  ui.updateEffectLiveValues = function(layer, ...args) { const result = update.call(this, layer, ...args); if (layer && this.drawerMode === 'effects') badges(layer); return result; };
  const selection = ui.setActiveEffectParameter;
  ui.setActiveEffectParameter = function(layer, ...args) { const result = selection.call(this, layer, ...args); badges(layer); return result; };
  const menu = ui.openEffectContextMenu;
  ui.openEffectContextMenu = function(layer, inst, spec, anchor) {
    const result = menu.call(this, layer, inst, spec, anchor), root = document.querySelector('.effectContextMenu');
    if (root) {
      const button = document.createElement('button');
      button.textContent = '✎  Ganti nama'; button.dataset.fxRename = '';
      root.prepend(button);
      button.onclick = () => {
        this.closeEffectContextMenu();
        const popup = panel('Nama efek', '<input maxlength="80" value="' + esc(name(inst)) + '" aria-label="Nama efek"><footer><button data-fx-rename-apply class="primary">Simpan</button></footer>');
        popup.querySelector('button[data-fx-rename-apply]').onclick = () => {
          const value = popup.querySelector('input').value.trim();
          if (!value || layer.locked || model.selectedLayer() !== layer) return;
          history.push(); inst.displayName = value; inst.expressionName = value;
          closeSurface(); changed(layer, 'effect-rename', true);
        };
      };
      const bounds = root.getBoundingClientRect();
      if (bounds.bottom > innerHeight - 8) root.style.top = Math.max(8, innerHeight - bounds.height - 8) + 'px';
    }
    return result;
  };
  const duplicate = ui.duplicateEffectInstance, singleCopy = ui.copyEffectInstance, singlePaste = ui.pasteEffectClipboard;
  const reset = ui.resetEffectInstance;
  ui.resetEffectInstance = function(layer, inst, ...args) {
    const result = reset.call(this, layer, inst, ...args);
    delete inst.paramExpressions; errors.delete(inst);
    changed(layer, 'effect-expression-reset', true);
    return result;
  };
  ui.copyEffectInstance = function(layer, inst, ...args) {
    const result = singleCopy.call(this, layer, inst, ...args);
    result.paramExpressions = clone(inst.paramExpressions); result.displayName = inst.displayName;
    this.effectClipboard = clone(result);
    return result;
  };
  ui.pasteEffectClipboard = function(layer, ...args) {
    const data = this.effectClipboard, inst = singlePaste.call(this, layer, ...args);
    if (inst && data) { inst.paramExpressions = clone(data.paramExpressions); inst.displayName = data.displayName; changed(layer, 'effect-expression-paste', true); }
    return inst;
  };
  ui.duplicateEffectInstance = function(layer, inst, ...args) {
    const before = new Set(layer.effectStack.map(i => i.instanceId)), result = duplicate.call(this, layer, inst, ...args);
    const added = layer.effectStack.find(i => !before.has(i.instanceId));
    if (added) { added.paramExpressions = clone(inst.paramExpressions); added.displayName = inst.displayName; changed(layer, 'effect-expression-duplicate', true); }
    return result;
  };
  const browserHTML = ui.effectBrowserHTML;
