// A new gallery entry, not a replacement for native Transform Motion Blur or
// imported AM effects. Reuse the embedded AM Link motionblur4 definition,
// animator and GPU passes verbatim; instance IDs/keyframe paths stay native.
(() => {
  const id = 'am_link_motion_blur';
  const original = omsEffectSpec('am_motionblur4');
  if (!original || OMS_EFFECT_BY_ID.has(id)) return;
  const copy = value => JSON.parse(JSON.stringify(value));
  const spec = {...copy(original), id, name: 'Motion Blur (AM Link)', category: 'Blur'};
  const labels = {tune: 'Kekuatan', usePos: 'Blur Posisi', useScale: 'Blur Skala', useAngle: 'Blur Rotasi'};
  for (const param of spec.params) param.label = labels[param.id] || param.label;
  spec.description = 'Shader AM Link · Adaptif terhadap gerak posisi, skala, dan rotasi layer/parent. Layer diam tetap tajam. Tidak melacak gerak objek di dalam video.';
  OMS_EFFECT_BY_ID.set(id, spec);
  OMS_EFFECT_CATALOG = [...OMS_EFFECT_CATALOG, spec];
  OMS_EFFECT_RENDERABLE.add(id);
  window.omsUnifiedEffects.catalog.set(id, spec);

  const cardHTML = ui.effectInstanceHTML;
  ui.effectInstanceHTML = function(layer, instance, ...args) {
    const html = cardHTML.call(this, layer, instance, ...args);
    if (instance?.specId !== id) return html;
    return html.replace('<div class="effectParams">', '<div class="effectParams"><div class="miniNote" data-am-link-motion-info>' + esc(spec.description) + '</div>');
  };

  // Snapshot only. No playback loop, decoder, history or extra GPU allocation.
  function stats() {
    const instances = [];
    for (const layer of model.layers || []) for (const instance of layer.effectStack || []) {
      if (instance?.specId !== id) continue;
      instances.push({layerId: layer.id, instanceId: instance.instanceId, enabled: instance.enabled !== false,
        strength: omsEffectRawValue(layer, instance, 'tune', model.time),
        position: omsEffectRawValue(layer, instance, 'usePos', model.time) >= .5,
        scale: omsEffectRawValue(layer, instance, 'useScale', model.time) >= .5,
        rotation: omsEffectRawValue(layer, instance, 'useAngle', model.time) >= .5});
    }
    return {version: 'V5.244', specId: id, sourceEffect: spec.amEffectId,
      implementation: 'embedded-AM-Link-motionblur4', shaderUnmodified: true,
      extraWebGLContexts: 0, frameHistoryEntries: 0, instances};
  }
  const snapshot = omsDiagnostics.snapshot;
  omsDiagnostics.snapshot = function(...args) {
    const result = snapshot.apply(this, args);
    result.amLinkMotionBlur = stats();
    return result;
  };
  window.omsAMLinkMotionBlur = {id, sourceEffect: spec.amEffectId, stats};
})();

